CREATE TABLE IF NOT EXISTS categories (id BIGSERIAL PRIMARY KEY, slug VARCHAR(80) UNIQUE NOT NULL, name VARCHAR(120) NOT NULL, description TEXT NOT NULL DEFAULT '', icon VARCHAR(40) NOT NULL DEFAULT 'sparkles');
CREATE TABLE IF NOT EXISTS commands (id BIGSERIAL PRIMARY KEY, slug VARCHAR(100) UNIQUE NOT NULL, name VARCHAR(140) NOT NULL, syntax VARCHAR(80) NOT NULL, description TEXT NOT NULL, instruction_template TEXT NOT NULL, example_input TEXT NOT NULL DEFAULT '', example_output TEXT NOT NULL DEFAULT '', difficulty VARCHAR(30) NOT NULL DEFAULT 'beginner', status VARCHAR(30) NOT NULL DEFAULT 'reviewed', tags JSONB NOT NULL DEFAULT '[]', limitations TEXT NOT NULL DEFAULT '', category_id BIGINT NOT NULL REFERENCES categories(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS providers (id BIGSERIAL PRIMARY KEY, slug VARCHAR(80) UNIQUE NOT NULL, name VARCHAR(120) NOT NULL, description TEXT NOT NULL DEFAULT '', docs_url VARCHAR(500) NOT NULL DEFAULT '', integration_status VARCHAR(40) NOT NULL DEFAULT 'directory');
CREATE TABLE IF NOT EXISTS workflows (id BIGSERIAL PRIMARY KEY, slug VARCHAR(100) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, description TEXT NOT NULL, category VARCHAR(80) NOT NULL DEFAULT 'general', difficulty VARCHAR(30) NOT NULL DEFAULT 'beginner', steps JSONB NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS saved_prompts (id BIGSERIAL PRIMARY KEY, owner_key VARCHAR(120) NOT NULL DEFAULT 'local-demo', title VARCHAR(180) NOT NULL, prompt TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_commands_name ON commands(name);
CREATE INDEX IF NOT EXISTS ix_commands_syntax ON commands(syntax);
CREATE INDEX IF NOT EXISTS ix_saved_prompts_owner ON saved_prompts(owner_key);
